package com.procurement.controller; import com.procurement.dto.ProcurementRequest; import com.procurement.entity.ProcurementRecord; import com.procurement.service.ProcurementService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/operator/procurement") public class ProcurementController {private final ProcurementService s;public ProcurementController(ProcurementService s){this.s=s;} @PutMapping("/{bookingId}/arrived") public ProcurementRecord arrived(@PathVariable Long bookingId){return s.arrive(bookingId);} @PutMapping("/{bookingId}/accept") public ProcurementRecord accept(@PathVariable Long bookingId,@Valid @RequestBody ProcurementRequest r){return s.accept(bookingId,r);} @PutMapping("/{bookingId}/reject") public ProcurementRecord reject(@PathVariable Long bookingId,@Valid @RequestBody ProcurementRequest r){return s.reject(bookingId,r);} }
